package com.example.HMS.service;

import com.example.HMS.dto.DoctorMapper;
import com.example.HMS.repository.AppointmentRepository;
import com.example.HMS.repository.DoctorRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.<Long>any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;

@ExtendWith(MockitoExtension.class)
class DoctorServiceTest {

    @Mock
    private AppointmentRepository appointmentRepository;

    private DoctorService doctorService;

    // GreyTest trace: fetchDoctorByAppointment | IF-1-TRUE | BR-087 -> TP-027 -> TC-044
    @Test
    void fetchDoctorByAppointment_NullId_ThrowsIllegalArgumentException() {
        // Arrange
        doctorService = new DoctorService((DoctorRepository) null, appointmentRepository, null, new DoctorMapper());
        Long appointmentId = null;

        // Act
        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> doctorService.fetchDoctorByAppointment(appointmentId));

        // Assert
        assertEquals("appointmentId cannot be empty", exception.getMessage());
        verify(appointmentRepository, never()).findById(any());
    }
}
